import requests
q='(NR1H3 OR "LXRalpha" OR "liver X receptor alpha") AND (HNF4A OR HNF4alpha OR "hepatocyte nuclear factor 4") AND (differentiation OR hepatocyte-like OR maturation)'
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmax':20,'retmode':'json'},timeout=20)
print('status',r.status_code)
js=r.json(); ids=js['esearchresult']['idlist']; print('IDs',ids)
if ids:
 s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
 for i in ids: print(i,s[i].get('title'),s[i].get('pubdate'))
else: print('No matching records')
